Task 4

Adding status col, based on bp in post trt. Using conditional logic. Done for all df in list

bpList[[1]]$status &lt;- character(20)
bpList[[2]]$status &lt;- character(10)

# Loop and logic for bp trt
for (i in seq_along(bpList[[1]]$post_bp)) {
  pbpVal &lt;- bpList[[1]]$post_bp[i]
  if (pbpVal &lt;= 120) { 
    bpList[[1]]$status[i] &lt;- "optimal"
  } else if (pbpVal &gt; 130){
    bpList[[1]]$status[i] &lt;- "high"
  } else if ((pbpVal &gt; 120) & (pbpVal &lt;= 130)) {
    bpList[[1]]$status[i] &lt;-  "borderline"
  } else {
    bpList[[1]]$status[i] &lt;- "error"
  }
}

# Loop and logic for bp placebo
for (i in seq_along(bpList[[2]]$post_bp)) {
  pbpVal &lt;- bpList[[2]]$post_bp[i]
  if (pbpVal &lt;= 120) { 
    bpList[[2]]$status[i] &lt;- "optimal"
  } else if (pbpVal &gt; 130){
    bpList[[2]]$status[i] &lt;- "high"
  } else if ((pbpVal &gt; 120) & (pbpVal &lt;= 130)) {
    bpList[[2]]$status[i] &lt;-  "borderline"
  } else {
    bpList[[2]]$status[i] &lt;- "error"
  }
}
